-- 📚 꼭집 주거 사전 — 출산자녀 자산 가산 3.79억·4,996만 / 4.13억·5,451만 · 국민·행복 · 2026
-- 재계산 SQL(관리 API에서 그대로 실행 · 읽기만). 범위: 공고일 2026년 · 유형은 housing_type_map 표준값.
-- 🔵 2026-11-09(조사 「사전 5차 후보 둘」 2-ⓒ · 우편함 「코드·운영 — 📚 사전 SQL 새 둘 + 개정 둘 …」 1) — 자격 행만 세던 셈(p1·p2·by_std·ex = 종전 값 그대로)에
--   reverify 가 가산 행을 접거나(스킬 「같은 자격에 붙는 조건은 행을 나누지 않고 verification_requirements 에 접는다」) 원문화해도 줄지 않는 셈을 더한다:
--   pol_p1·pol_p2 = 정책 문장에 금액(「1명 : 37,900」·「379,000,000원」 / 「2명 : 41,300」·「413,000,000원」) · vr = 자격 행 verification_requirements 의
--   가산 키(그 행 asset_limit = 3.45억 ∧ 키에 「가산」 ∧ 키·값에 출산·출생 ∧ 키·값에 자산 — 기준 3.45억에 붙는 가산만) · col = 자격 행 asset_limit_birth1 = 3.79억 또는 asset_limit_birth2 = 4.13억 ·
--   any = 넷(종전 자격 행 · 정책 문장 · vr · col) 중 하나라도.
-- 확인 2026-11-09 · 실행 약 5초(관리 API 왕복) · 결과:
-- {"p1": 6, "p2": 6, "by_std": {"국민임대": 2, "매입임대": 1, "행복주택": 3}, "ex": ["20652_1_서울특별시_영등포구", "2015122300020328", "2015122300020297", "2015122300020292"], "pol_p1": 56, "pol_p2": 56, "vr": 74, "col": 77, "any": 125, "any_by_std": {"행복주택(신혼희망)": 10, "매입임대": 21, "국민임대": 66, "행복주택": 15, "통합공공임대": 11, "전세임대": 2}, "any_not_old_ex": ["SH_310650", "21477_1_충청북도_제천시", "21442_1_제주특별자치도_서귀포시", "20857_1_제주특별자치도_서귀포시", "20648_1_경기도_광명시", "20647_1_경기도_광명시"]}
-- (종전 2026-10-13: {"p1": 9, "p2": 9, "by_std": {"국민임대": 5, "매입임대": 1, "행복주택": 3}} — 자격 행만 센 값 · 10-26 reverify 가 김제하동 셋의 가산 행을 vr 로 접어 6)
with a as(select distinct on(x.announcement_id)x.announcement_id,coalesce(m.std_type,x.housing_type)astd,extract(year from coalesce(x.announcement_date,x.created_at::date))::int yr from announcements x left join housing_type_map m on m.source_table='announcements' and m.source=x.source and m.housing_type=x.housing_type order by x.announcement_id,(x.source='LH')desc,x.created_at desc),e as(select distinct ec.announcement_id,coalesce(m.std_type,ec.housing_type)std,ec.asset_limit,ec.car_limit from eligibility_criteria ec join a on a.announcement_id=ec.announcement_id and a.yr=2026 left join housing_type_map m on m.source_table='eligibility_criteria' and m.housing_type=ec.housing_type where ec.announcement_id is not null),old as(select distinct announcement_id from e where asset_limit in(379000000,413000000)),pol as(select p.announcement_id,bool_or(t~'1\s*명\s*:?\s*37,?900|379,000,000')p1,bool_or(t~'2\s*명\s*:?\s*41,?300|413,000,000')p2 from(select announcement_id,regexp_replace(content_raw,'\s+',' ','g')t from announcement_policies) p join a on a.announcement_id=p.announcement_id and a.yr=2026 group by 1),vr as(select distinct ec.announcement_id from eligibility_criteria ec join a on a.announcement_id=ec.announcement_id and a.yr=2026 cross join lateral jsonb_each_text(case when jsonb_typeof(ec.verification_requirements)='object' then ec.verification_requirements else '{}'::jsonb end) kv where ec.asset_limit=345000000 and kv.key~'가산' and (kv.key||kv.value)~'출산|출생' and (kv.key||kv.value)~'자산'),col as(select distinct ec.announcement_id from eligibility_criteria ec join a on a.announcement_id=ec.announcement_id and a.yr=2026 where ec.asset_limit_birth1=379000000 or ec.asset_limit_birth2=413000000),u as(select announcement_id from old union select announcement_id from pol where p1 or p2 union select announcement_id from vr union select announcement_id from col)select json_build_object('p1',(select count(distinct announcement_id) from e where asset_limit=379000000 and car_limit=49960000),'p2',(select count(distinct announcement_id) from e where asset_limit=413000000 and car_limit=54510000),'by_std',(select json_object_agg(std,n) from(select std,count(distinct announcement_id)n from e where asset_limit in(379000000,413000000) group by 1)q),'ex',(select json_agg(i) from(select distinct announcement_id i from e where asset_limit=413000000 order by 1 desc limit 4)q),'pol_p1',(select count(*) from pol where p1),'pol_p2',(select count(*) from pol where p2),'vr',(select count(*) from vr),'col',(select count(*) from col),'any',(select count(*) from u),'any_by_std',(select json_object_agg(astd,n) from(select a.astd,count(*)n from u join a using(announcement_id) group by 1)q),'any_not_old_ex',(select json_agg(i) from(select announcement_id i from u except select announcement_id from old order by 1 desc limit 6)q))j;
